layer.css:
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-bg); border-top: 1px solid var(--ryt-border); border-right: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-left: 1px solid var(--ryt-border); border-radius: 8px; transition: box-shadow 0.3s, border-color 0.3s }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: inter, "segoe ui", "apple sd gothic neo", "noto sans kr", "malgun gothic", roboto, "helvetica neue", Arial, sans-serif, "apple color emoji", "segoe ui emoji"; font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 0px; font-family: inter, "segoe ui", "apple sd gothic neo", "noto sans kr", "malgun gothic", roboto, "helvetica neue", Arial, sans-serif, "apple color emoji", "segoe ui emoji"; font-size: 20px; font-weight: 400; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="button"] { color: var(--ryt-text); background-color: var(--ryt-border); border-radius: 50%; font-family: inter, "segoe ui", "apple sd gothic neo", "noto sans kr", "malgun gothic", roboto, "helvetica neue", Arial, sans-serif, "apple color emoji", "segoe ui emoji"; font-weight: 400; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 1px; padding-right: 6px; padding-bottom: 1px; padding-left: 6px; transition: all }
[data-ryt="category"], [data-ryt="tags"] li { color: var(--ryt-text); background-color: var(--ryt-border); border-radius: 4px; font-family: inter, "segoe ui", "apple sd gothic neo", "noto sans kr", "malgun gothic", roboto, "helvetica neue", Arial, sans-serif, "apple color emoji", "segoe ui emoji"; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 3.2px; padding-right: 8px; padding-bottom: 3.2px; padding-left: 8px; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: inter, "segoe ui", "apple sd gothic neo", "noto sans kr", "malgun gothic", roboto, "helvetica neue", Arial, sans-serif, "apple color emoji", "segoe ui emoji"; font-size: 14.4px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: inter, "segoe ui", "apple sd gothic neo", "noto sans kr", "malgun gothic", roboto, "helvetica neue", Arial, sans-serif, "apple color emoji", "segoe ui emoji"; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.3s }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: inter, "segoe ui", "apple sd gothic neo", "noto sans kr", "malgun gothic", roboto, "helvetica neue", Arial, sans-serif, "apple color emoji", "segoe ui emoji"; font-size: 24px; font-weight: 400; font-style: normal; line-height: 1.4; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: #0055bb }
[data-ryt="category"]:hover, [data-ryt="tags"] li:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: black; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
article[data-ryt="rec-card"]:hover { box-shadow: 0 4px 12px color-mix(in srgb, var(--ryt-text) 10%, transparent) }
